    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Actual mixed-history root nondegeneracy and strong extraction", H("HistoryCertificate"),
        Blocks(
            Paragraph(Text("Every prescribed PhysicalHistory.MixedHistory n G g has a genuine singleton face in the literal raw root g.rows.root, including in the original ambient type V with its inactive ghosts. The seed has three tree-edge labels and singleton facets f 0, f 1, f 2; it does not have four tree-edge labels. An attachment uses mixed_ground_card old and card_erase_add_one at the retained port to obtain an old label in old.ground.erase i.e. Index 1 : Fin i.width exists at every width at least 3 and differs from the interface index 0. physicalWheelStep_rows_right identifies its actual surviving physical row. rimRows.row_supported and freshness place that row wholly in the fresh right ground, away from the chosen old label. This proves singleton membership in the actual raw complement root before any nonempty projection. No row index, duplicate row, projected empty or singleton row, or ghost coordinate is discarded.")),
            Paragraph(Text("certificate consumes exactly HistoryRecursion.allCornersOutput h at A = B = empty. Its private empty_corner proof uses actual root support, and the residual is the complete g.ground. The private strongOfSingleton eliminator contradicts literal VOID and literal UNIT using the derived singleton; it returns the strong branch itself. The resulting Certificate g.ground g.rows.root keeps its computed core, critical family and coordinate vertex, critical top absence, every proper boundary, antichain, and both ordered native sequences with real evolving cofaces. main has type Sequence (project g.rows.root) (project (endpoint c.core c.critical)); separate has type Sequence (project c.core) (project (delta {c.vertex})). The latter starts at C ALONE. No requested Certificate, Output, collapse, supplied singleton, leaf, classification or core supplier is an input of the public history declarations.")),
            Paragraph(Text("Existing original-coordinate geometric consumers apply directly to c.main and c.separate: FiniteRelativeSimplicialCollapse.Sequence.collapseHomotopy is relative from the identity to inclusion composed with sequenceRetraction; collapseHomotopy_fixed fixes every point of the full final realization; sequenceRetraction_inclusion recovers every final point after the literal coordinate inclusion. Sequence.pairs and frames are the actual ordered native objects, and pairs_cast and frames_cast preserve them under equality transport. FiniteConeCollapse.realization_mem_iff supplies a faceSimplex whose outside coordinates are zero; support in g.ground therefore keeps every inactive coordinate zero at every homotopy time. FiniteConeUnionWedge.realizationInclusion keeps the same coordinate function. This is reuse of existing APIs, with no additional renamed application theorem or homotopy wrapper. A general sphere-wedge identification of the multi-critical endpoint is not supplied by these SDR APIs and is not asserted here.")),
            Paragraph(Text("These are fallible, uncompiled source candidates. The separate total-solver review and Q01 repair were not inspected, consumed or assumed accepted. Completed focused K01/F01 reviews cover only their exact repairs. No Lean, kernel, Scribe compiler/emitter, Reg, report, gate, native, remote or full-goal acceptance is claimed; original broad mathematical and delivery obligations remain. The new public singleton theorem still needs its faithful mirrored escape audit under the eventual authorized delivery scope.")),
            Paragraph(Text("SOURCE_ONLY_UNCOMPILED. Literal source, not compiled declaration metadata. Common context: noncomputable section; open Set Finset; namespace D5.S3.Geometry.OriginalLabelTwoSum.HistoryCertificate; open OriginalLabelTwoSum HistoryCorners HistoryLeafCap PhysicalHistory; variable {V : Type*} [Fintype V] [DecidableEq V]. Import: D5.S3.Geometry.OriginalLabelTwoSum.HistoryRecursion. Private consumed plumbing, with no private DeclarationHandle: literal source declarations and bodies:\nprivate theorem empty_corner {G : Type} (g : GraphData G V) :\n    corner g.ground ∅ ∅ g.rows.root = g.rows.root := by\n  apply SetLike.ext\n  intro s\n  change (s ⊆ residual g.ground ∅ ∅ ∧ s ∪ ∅ ∈ g.rows.root) ↔ s ∈ g.rows.root\n  simp only [residual, Finset.union_empty, Finset.sdiff_empty]\n  exact ⟨fun hs => hs.2, fun hs => ⟨g.rows.root_supported s hs, hs⟩⟩\n\nprivate def strongOfSingleton {W : Finset V} {K : Family V}\n    (o : Output W K) (has : ∃ x : V, ({x} : Finset V) ∈ K) : Certificate W K := by\n  cases o with\n  | void he =>\n      apply False.elim\n      obtain ⟨x, hx⟩ := has\n      rw [he] at hx\n      exact hx\n  | unit he =>\n      apply False.elim\n      obtain ⟨x, hx⟩ := has\n      rw [he] at hx\n      change ({x} : Finset V) ⊆ ∅ at hx\n      exact Finset.not_mem_empty x (hx (Finset.mem_singleton_self x))\n  | strong c => exact c")),
            Describe.Lean(DescribeId.Create("root-has-singleton"), DeclarationHandle.Create("D5/S3/Geometry/OriginalLabelTwoSum/HistoryCertificate.root_has_singleton"), H("root_has_singleton"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("SOURCE_ONLY_UNCOMPILED. Literal source, not compiled declaration metadata. Common context: noncomputable section; open Set Finset; namespace D5.S3.Geometry.OriginalLabelTwoSum.HistoryCertificate; open OriginalLabelTwoSum HistoryCorners HistoryLeafCap PhysicalHistory; variable {V : Type*} [Fintype V] [DecidableEq V]. Import: D5.S3.Geometry.OriginalLabelTwoSum.HistoryRecursion. Exact public SOURCE declaration and body:\ntheorem root_has_singleton {n : Nat} {G : Type} {g : GraphData G V}\n    (h : MixedHistory n G g) : ∃ x : V, ({x} : Finset V) ∈ g.rows.root := by\n  cases h with\n  | seed f =>\n      refine ⟨f 0, ?_⟩\n      rw [seed_root]\n      exact Or.inl (Or.inl (show ({f 0} : Finset V) ⊆ {f 0} from le_rfl))\n  | @attach n G g old i =>\n      have hcard := mixed_ground_card old\n      have herase := Finset.card_erase_add_one i.retained\n      have hold : (g.ground.erase i.e).Nonempty :=\n        Finset.card_pos.mp (by omega)\n      obtain ⟨x, hx⟩ := hold\n      let d : Fin i.width := ⟨1, by have := i.atLeastThree; omega⟩\n      have hd : d ≠ AllMWheel.interfaceRow i.width i.atLeastThree := by\n        intro heq\n        have hv := congrArg Fin.val heq\n        change 1 = 0 at hv\n        omega\n      let c := (physicalWheelStep_chords g i).symm (.inr ⟨d, hd⟩)\n      have hrow : (physicalWheelStep g i).data.rows.row c ⊆\n          (AllMWheel.ground i.width).image i.labels := by\n        change (physicalWheelStep g i).data.rows.row\n          ((physicalWheelStep_chords g i).symm (.inr ⟨d, hd⟩)) ⊆ _\n        rw [physicalWheelStep_rows_right]\n        exact Finset.image_subset_image\n          ((AllMWheel.rimRows i.width (by have := i.atLeastThree; omega)).row_supported d)\n      have hxrow : x ∉ (physicalWheelStep g i).data.rows.row c := by\n        intro hxc\n        exact Finset.disjoint_left.mp i.fresh (Finset.mem_of_mem_erase hx) (hrow hxc)\n      refine ⟨x, c, Finset.singleton_subset_iff.mpr ?_⟩\n      refine Finset.mem_sdiff.mpr ⟨?_, hxrow⟩\n      change x ∈ g.ground.erase i.e ∪ (AllMWheel.ground i.width).image i.labels\n      exact Finset.mem_union_left _ hx"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("certificate"), DeclarationHandle.Create("D5/S3/Geometry/OriginalLabelTwoSum/HistoryCertificate.certificate"), H("certificate"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("SOURCE_ONLY_UNCOMPILED. Literal source, not compiled declaration metadata. Common context: noncomputable section; open Set Finset; namespace D5.S3.Geometry.OriginalLabelTwoSum.HistoryCertificate; open OriginalLabelTwoSum HistoryCorners HistoryLeafCap PhysicalHistory; variable {V : Type*} [Fintype V] [DecidableEq V]. Import: D5.S3.Geometry.OriginalLabelTwoSum.HistoryRecursion. Exact public SOURCE declaration and body:\ndef certificate {n : Nat} {G : Type} {g : GraphData G V}\n    (h : MixedHistory n G g) : Certificate g.ground g.rows.root := by\n  have o := HistoryRecursion.allCornersOutput h ∅ ∅\n    (Finset.empty_subset _) (Finset.empty_subset _) (by simp)\n  have hground : residual g.ground ∅ ∅ = g.ground := by\n    simp only [residual, Finset.union_empty, Finset.sdiff_empty]\n  rw [hground, empty_corner g] at o\n  exact strongOfSingleton o (root_has_singleton h)"))), DescribeRole.Definition)
        )));
